using System.Data.Common;
using Microsoft.Data.SqlClient;
using Npgsql;
using MySqlConnector;
using FirebirdSql.Data.FirebirdClient;

namespace SnapData.IntegrationTests;

public sealed class InsertManyProviderTests
{
    [PostgresFact]
    public Task PostgreSql_batches() => RunAsync(NpgsqlFactory.Instance,
        "SNAPDATA_POSTGRES_CONNECTION", PostgresQueryCompiler.Instance, "BIGINT GENERATED BY DEFAULT AS IDENTITY");

    [SqlServerFact]
    public Task SqlServer_batches() => RunAsync(SqlClientFactory.Instance,
        "SNAPDATA_SQLSERVER_CONNECTION", SqlServerQueryCompiler.Instance, "BIGINT IDENTITY");

    [MySqlFact]
    public Task MySql_batches() => RunAsync(MySqlConnectorFactory.Instance,
        "SNAPDATA_MYSQL_CONNECTION", MySqlQueryCompiler.Instance, "BIGINT AUTO_INCREMENT");

    [FirebirdFact]
    public Task Firebird_batches() => RunAsync(FirebirdClientFactory.Instance,
        "SNAPDATA_FIREBIRD_CONNECTION", FirebirdQueryCompiler.Instance, "BIGINT GENERATED BY DEFAULT AS IDENTITY");

    private static async Task RunAsync(DbProviderFactory factory, string variable, IQueryCompiler compiler, string identity)
    {
        var table = "BATCH_" + Guid.NewGuid().ToString("N")[..20].ToUpperInvariant();
        var mapping = new EntityMappingProvider(new MappingOptions { TableName = _ => table });
        var database = new SnapDatabase(factory, Environment.GetEnvironmentVariable(variable)!, compiler, mapping);
        await using var session = await database.OpenSessionAsync();
        var quotedTable = compiler == MySqlQueryCompiler.Instance ? $"`{table}`"
            : compiler == SqlServerQueryCompiler.Instance ? $"[{table}]" : $"\"{table}\"";
        var id = compiler == FirebirdQueryCompiler.Instance ? "\"ID\"" : "id";
        var name = compiler == FirebirdQueryCompiler.Instance ? "\"DISPLAY_NAME\"" : "display_name";
        await session.ExecuteAsync($"CREATE TABLE {quotedTable} ({id} {identity} PRIMARY KEY, {name} VARCHAR(40) NOT NULL UNIQUE)");
        try
        {
            var items = Enumerable.Range(1, 5).Select(i => new Item { Name = "name" + i }).ToArray();
            var result = await session.InsertManyAsync(items, new InsertManyOptions { BatchSize = 2 });
            Assert.Equal(5, result.RowsSubmitted);
            Assert.Equal(compiler.Capabilities.MultiRowInsert ? 3 : 5, result.StatementsExecuted);
            Assert.Equal(5L, result.AffectedRows);
            Assert.All(items, item => Assert.Equal(0, item.Id));
            Assert.Equal(items.Select(item => item.Name),
                (await session.From<Item>().OrderBy(item => item.Name).ToListAsync()).Select(item => item.Name));

            await using (var transaction = await session.BeginTransactionAsync())
            {
                await transaction.InsertManyAsync(new[] { new Item { Name = "rolled-back" } });
                Assert.Equal(6, await transaction.From<Item>().CountAsync());
                await transaction.RollbackAsync();
            }
            Assert.Equal(5, await session.From<Item>().CountAsync());

            var duplicate = new[] { new Item { Name = "partial" }, new Item { Name = "name1" } };
            await Assert.ThrowsAnyAsync<DbException>(() => session.InsertManyAsync(duplicate,
                new InsertManyOptions { BatchSize = 1 }));
            Assert.Equal(5, await session.From<Item>().CountAsync());
            await Assert.ThrowsAnyAsync<DbException>(() => session.InsertManyAsync(duplicate,
                new InsertManyOptions { BatchSize = 1, Atomic = false }));
            Assert.Equal(6, await session.From<Item>().CountAsync());
        }
        finally { await session.ExecuteAsync($"DROP TABLE {quotedTable}"); }
    }

    private sealed class Item
    {
        [Key, Column("id"), DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long Id { get; set; }
        [Column("display_name")] public string Name { get; set; } = "";
    }
}
